head.script:
scwin.screenId = "jldods20001";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_lawTitle", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("relLawDtlNm2")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// [A] 초기 목록 미해결 — jldods20001: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.editor = undefined; try { scwin.editor = /* sdd-asis-lifecycle:begin editor — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Dext5editor("dext5editor1")/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldods20001' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods20001.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.grd_searchLawList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_searchLawList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_searchLawList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_searchLawList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.search_detail === 'function') { scwin.search_detail(r["relLawDtlNo"], r["relLawDtlNm"]); } else { console.error('[sdd] 행 동작 미정의: scwin.search_detail (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.search_detail'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_searchLawList.oncellclick' });
    }
};

/**
 * @event
 * @name scwin.input_33_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.input_33_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin input_33_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.openRelLaw()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods20001.input_33_onclick' }); }
};

/**
 * @event
 * @name scwin.input_34_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.input_34_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin input_34_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.regRelLaw()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods20001.input_34_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.search_detail
 * @author Inswave
 * @date 2026. 09. 29
 * @param relLawDtlNo relLawDtlNm
 * @returns
 * @hidden N
*/
scwin.search_detail = function (relLawDtlNo, relLawDtlNm) {
    /* sdd-asis-lifecycle:begin search_detail — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const curRelLawDtlNo = $('#relLawDtlNo').val();
    if (curRelLawDtlNo === relLawDtlNo) {
        return;
    }
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('method', "lawMain") : console.warn('[sdd] hiddenStore 부재: method'));
    $('#relLawDtlNo').val(relLawDtlNo);
    $c.util.getComponent('relLawDtlNm').setValue(relLawDtlNm);
    $('#headerKeywrdForm')[0].submit();
    blockLoading();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.regRelLaw
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.regRelLaw = function () {
    /* sdd-asis-lifecycle:begin regRelLaw — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const a = DEXT5.getBodyValue("dext5editor1");
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('relLawDtlContn', a) : console.warn('[sdd] hiddenStore 부재: relLawDtlContn'));
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('method', "updateRelLawDtl") : console.warn('[sdd] hiddenStore 부재: method'));
    $('#headerKeywrdForm')[0].submit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.dext_editor_loaded_event
 * @author Inswave
 * @date 2026. 09. 29
 * @param editor
 * @returns
 * @hidden N
*/
scwin.dext_editor_loaded_event = function (editor) {
    /* sdd-asis-lifecycle:begin dext_editor_loaded_event — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    DEXT5.setBodyValue(dma_hiddenStore.get("relLawDtlContn"), editor.ID);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchRelLaw
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.searchRelLaw = async function () {
    /* sdd-asis-lifecycle:begin searchRelLaw — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const formCd = $('#roomNo option:selected').val();
    if (formCd.length == 0) {
        await $c.win.alert("법규전문을 선택해 주세요.");
        return;
    }
    scwin.searchList("1");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchRelLaw2
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.searchRelLaw2 = async function () {
    /* sdd-asis-lifecycle:begin searchRelLaw2 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const formCd = dma_hiddenStore.get("lawNm");
    if (formCd.length == 0) {
        await $c.win.alert("단위조항명을 입력해 주세요.");
        return;
    }
    scwin.searchList("2");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchList
 * @author Inswave
 * @date 2026. 09. 29
 * @param div
 * @returns
 * @hidden N
*/
scwin.searchList = function (div) {
    /* sdd-asis-lifecycle:begin searchList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('method', "lawMain") : console.warn('[sdd] hiddenStore 부재: method'));
    if (div === "1") {
        ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('lawNm', "") : console.warn('[sdd] hiddenStore 부재: lawNm'));
    } else {
        if (div === "2") {
            ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('roomNo', "") : console.warn('[sdd] hiddenStore 부재: roomNo'));
        }
    }
    $('#headerKeywrdForm')[0].submit();
    blockLoading();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.openRelLaw
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.openRelLaw = function () {
    /* sdd-asis-lifecycle:begin openRelLaw — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.openPopup("", { id: "관련법규", scrollbars: true, width: "1120", height: "800", resizable: true, type: "pageFramePopup" }, {});
    let form = create_form('relLawForm', 'POST', '/insert/findRelLaw.do', "관련법규");
    form = add_input(form, 'relLawDtlNo', $('#relLawDtlNo').val());
    form = add_input(form, 'method', "findRelLawList");
    document.body.insertBefore(form, null);
    form.submit();
    /* sdd-asis-lifecycle:end */
};
